// park.cpp: the single garage-PARK controller (g_ParkController 0x669AE4, operator_new(0x48) in Game_Ctor). Mission op PARK(car, door) -> ParkController_Start; ParkController_Update each GameTick pulls the car through the door, then kills passengers, puts the driver outside, removes the car. Only one park at a time.
struct ParkController {
    Car *car; /* 0x0 Car being parked (PARK arg 1). Set by ParkController_Start 0x489BC0, cleared at finish 0x489680 (state 3). Read by ParkController_IsCar 0x493540 / IsCarInside 0x434AF0 */
    Car *lastParkedCar; /* 0x4 Car of the previous finished park (state 3 copies car here before clearing it, 0x489680). Door_CarMayOpen mode 6 -> ParkController_IsLastParkedCar 0x44C870 */
    dword lastParkedCarId; /* 0x8 Car.id (+0x6C) of lastParkedCar, guards against a reused Car slot (0x44C870) */
    PARK_STATE state; /* 0xc PARK_STATE. 1 by ParkController_Start, 2/3 by ParkController_Update, 0 by ParkController_Reset. ==3 -> HAS_PARK_FINISHED (0x476AC0) */
    DoorSlot *door; /* 0x10 Garage door (PARK arg 2, DOOR_DATA). Door_GetBlockPos / Door_HasTwoFaces in Start; Door_CloseBothFaces + Door_ClearByte2C at finish (0x489680) */
    Ped *lastDriver; /* 0x14 Last non-null car->driver (+0x54) seen in state 1 (0x489680). At finish, if the car has no driver and this ped stands inside the area, it is moved to exitPos (unless noRespawn) */
    Vec2 areaMin; /* 0x18 Garage interior rectangle min (x,y), Fix16 blocks. Built by ParkController_Start from the door block + side + margin (1.0, or 2.0 for long cars), +1 block across for a double door. Sprite_FindCornersInsideRect(min,max) in Update; AssertAreaClear checks it for walls */
    Vec2 areaMax; /* 0x20 Garage interior rectangle max (x,y), see areaMin */
    Vec2 pullStep; /* 0x28 Per-tick pull-in force: (midpoint of the two inside corners - car centre), normalised * 0.1 (DAT_00669C9C), passed to CarPhysics_ApplyMassKick(physics, &pullStep) at 0x4898CB / 0x489AAC. Zero -> straight to state 2 */
    Vec2 exitPos; /* 0x30 Where the driver is put on foot at finish: 0.8 block outside the door face, 0.5 along it (Start 0x48A167); Ped_PlaceInWorldOnFoot in Update */
    DOOR_SIDE doorSide; /* 0x38 DOOR_SIDE of the door's face A (Door_GetBlockPos 4th out = DoorFace.side). Chooses area/exit geometry (Start) and exit heading (ParkController_GetExitHeading) */
    byte settleTicks; /* 0x3c Countdown from 30 (0x1E, Ctor/Start) once all 4 corners are inside; reaches 0 -> state 3 (0x489680) */
    byte carInside; /* 0x3d Latched 1 when all 4 corners are inside the area or no pull is needed (0x489680). Then the car stops being pulled and ParkController_IsCarInside makes Ped_Obj2_EnterCar fail for it. Cleared by Start */
    byte parkSerial; /* 0x3e Incremented by every ParkController_Start (255 wraps to 1, never 0) and returned by it; Script_Op_PARK ignores the value. Only reader is Start itself */
    byte noRespawn; /* 0x3f 1 = PARK_NO_RESPAWN (opcode 0x118, ParkController_SetNoRespawn 0x476AD0): at finish the driver is NOT placed outside, he is removed with the car. Never cleared back to 0 (see report hazard) */
    byte isLongCar; /* 0x40 Car_IsLongerThanCraneLimit (sprite length > 1.0 block) at Start; widens the area margin from 1.0 to 2.0 blocks */
    uint8_t _gap_0x41[0x3];
    dword pullTicks; /* 0x44 Ticks spent in state 2; reset by Start; >= 300 (~10 s) forces state 3 even if the car is not inside (0x489680) */
};

